<script setup lang="ts">
import {computed,ref,watch,onUnmounted} from 'vue'
import {authState,hasPermission} from '../services/auth'
import {planAlertsApi,type PlanAlertState,type EntryMode} from '../services/planAlerts'
import {formatTime} from '../utils/format'
import PlanAlertEvents from './PlanAlertEvents.vue'
const props=defineProps<{caseId:string;planId:string;editable:boolean}>()
const data=ref<PlanAlertState|null>(null),loading=ref(false),saving=ref(false),error=ref(''),mode=ref<EntryMode>('BREAKOUT')
const canRead=computed(()=>!!authState.user&&hasPermission('paper.read')&&hasPermission('market.read')),canWrite=computed(()=>hasPermission('paper.write'))
const context=computed(()=>JSON.stringify([props.caseId,props.planId,authState.user?.id,authState.user?.tenantId,authState.user?.permissions]))
const labels:Record<string,string>={STARTING:'等待首次检查',READY:'已建立行情观察',STALE:'行情过时或休市',PAUSED:'已暂停',EXPIRED:'已到期停止',SUPERSEDED:'旧版本已停止',FORBIDDEN:'权限失效已停止',ERROR:'等待服务恢复'}
let generation=0,inflight=false
async function load(quiet=false){if(inflight||saving.value||!canRead.value)return;const ticket=++generation;inflight=true;if(!quiet){data.value=null;error.value='';loading.value=true}try{const r=await planAlertsApi.read(props.caseId,props.planId);if(ticket===generation){data.value=r;if(r.subscription)mode.value=r.subscription.entryMode;error.value=''}}catch(e){if(ticket===generation)error.value=e instanceof Error?e.message:'计划提醒暂不可用。'}finally{if(ticket===generation){inflight=false;loading.value=false}}}
watch(context,()=>{++generation;inflight=false;loading.value=false;saving.value=false;data.value=null;error.value='';mode.value='BREAKOUT';void load()},{immediate:true})
async function toggle(){if(!data.value||saving.value||!canWrite.value)return;const enabled=!data.value.subscription?.enabled;if(enabled&&!props.editable)return;const ticket=++generation;inflight=false;saving.value=true;error.value='';try{const r=await planAlertsApi.edit(props.caseId,props.planId,enabled,mode.value,data.value.subscription?.revision??0);if(ticket===generation)data.value=r}catch(e){if(ticket===generation)error.value=e instanceof Error?e.message:'操作失败，请刷新后重试。'}finally{if(ticket===generation)saving.value=false}}
async function ack(id:string){const ticket=++generation;inflight=false;loading.value=false;saving.value=true;try{await planAlertsApi.ack(id);if(ticket===generation){saving.value=false;await load(true)}}catch(e){if(ticket===generation)error.value=e instanceof Error?e.message:'标记失败。'}finally{if(ticket===generation)saving.value=false}}
const timer=window.setInterval(()=>{if(!document.hidden)void load(true)},15000)
onUnmounted(()=>{++generation;window.clearInterval(timer)})
</script>
<template><section class="private-plan-alerts"><header><h3>本计划专属提醒</h3><button v-if="canRead" :disabled="loading||saving" @click="load()">刷新提醒</button></header><p>服务器每分钟尝试读取近时行情。仅记录相邻采样穿越，不代表逐笔触达、15分钟收盘确认或成交。每个计划的入场、保护、目标、到期各记录一次；历史证据保留。</p><p v-if="!canRead">需要行情与档案读取权限才能查看。</p><p v-if="error" role="alert">{{error}} <span v-if="data">下方为上次成功快照。</span></p><p v-if="loading" role="status">正在读取计划提醒…</p><template v-if="data"><p v-if="data.subscription" role="status">{{labels[data.subscription.status]??data.subscription.status}} · 最近检查 {{formatTime(data.subscription.checkedAt)}}<br/>{{data.subscription.message}}</p><p v-else>尚未启用本版本专属提醒。</p><label>入场穿越方式<select v-model="mode" :disabled="!!data.subscription||!editable||!canWrite||saving"><option value="BREAKOUT">顺计划方向突破参考价</option><option value="PULLBACK">反计划方向回踩参考价</option></select></label><p>启用、恢复及行情中断后的首笔有效数据只建立基线；间隔超过90秒时不推断中间路径。计划修订停止旧版本；到期记录后停止订阅。此处只提供站内提醒。</p><button v-if="canWrite" :disabled="saving||(!data.subscription?.enabled&&!editable)" @click="toggle">{{data.subscription?.enabled?'暂停本计划提醒':'启用本计划提醒'}}</button><p v-if="!editable&&!data.subscription?.enabled">需先保存最新且未过期的计划。改变入场方式也需新建计划版本。</p><PlanAlertEvents :items="data.events" :can-write="canWrite" :busy="saving" @ack="ack"/><p v-if="!data.events.length">本版本尚无专属触发记录。</p></template></section></template>
<style scoped>
.private-plan-alerts{padding:1rem;border:1px solid var(--color-line);border-radius:.8rem;background:var(--color-surface);min-width:0}.private-plan-alerts>header{display:flex;justify-content:space-between;align-items:center;gap:.5rem;flex-wrap:wrap}h3{font-size:.95rem;margin:.4rem 0}p,label,button,select{font-size:.73rem;line-height:1.8}p{color:var(--color-ink-secondary)}label{display:grid;gap:.4rem;margin:.8rem 0}select{width:100%;min-width:0;border:1px solid var(--color-line);background:var(--color-surface);padding:.55rem;border-radius:.4rem;color:var(--color-ink)}button{border:1px solid var(--color-line);background:var(--color-accent-soft);color:var(--color-accent);padding:.5rem .65rem;border-radius:.4rem;cursor:pointer}button:disabled{opacity:.5;cursor:default}[role=alert]{padding:.6rem;background:#fff0ee;color:#9e352d;border-radius:.4rem}
</style>
